package com.brasa.restaurant.model;import com.brasa.restaurant.enums.Enums.StatusMesa;import jakarta.persistence.*;@Entity@Table(name="mesas",uniqueConstraints=@UniqueConstraint(columnNames={"restaurante_id","numero"}))public class Mesa extends BaseEntity{@Column(name="restaurante_id",nullable=false)private String restauranteId;private int numero;@Enumerated(EnumType.STRING)private StatusMesa status=StatusMesa.ABERTA;public String getRestauranteId(){return restauranteId;}public void setRestauranteId(String v){restauranteId=v;}public int getNumero(){return numero;}public void setNumero(int v){numero=v;}public StatusMesa getStatus(){return status;}public void setStatus(StatusMesa v){status=v;}}
